//
// NOVEL (hand-authored) — not generated by CLI Printing Press.
// Recorded in .printing-press-patches/garmin-sync-superseded.json.
//
// `garmin-pp-cli sync` — a pointer to `history`, and nothing else.
//
// The generated sync.go is untouched and still compiles: newSyncCmd is simply
// never registered. root.go registers this command under the name `sync`
// instead, so the generated walker is unreachable from the command tree while
// remaining exactly what a reprint would emit.
//
// Why the generated verb is a dead end here: the press emits `sync` with every
// SQLite store, and its walker can page a flat list, add a `since=` filter the
// list endpoint declares, and walk a parent table's rows into a child URL.
// Garmin's daily statistics are behind date-range endpoints whose URL carries
// the range and which refuse more than 28 days per call, or behind per-day
// endpoints answering for one date; none of those is a shape the walker has.
// Running one account through both verbs stored the activity feed and the
// per-activity heart-rate zones twice under different resource names, and
// re-paged the whole feed on every `sync`, because Garmin's activity list
// declares no filter the generator recognises. `history` carries the three
// fetches only `sync` used to make — activity detail, splits and the
// heart-rate-zone configuration — so one command now fills the archive.
//
// pp:data-source computed
package cli

import (
	"encoding/json"
	"errors"
	"fmt"

	"github.com/spf13/cobra"
)

// garminSyncSupersededMessage is the whole of this command's human output.
const garminSyncSupersededMessage = "sync is superseded by history; run `garmin-pp-cli history`"

// garminSyncSupersededEvent is the machine equivalent, one JSON line.
const garminSyncSupersededEvent = "sync_superseded"

func newGarminSyncStubCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "sync",
		Short: "Superseded by `history`, which fills the same local archive",
		Long: `Superseded. Run ` + "`garmin-pp-cli history`" + ` instead.

This CLI keeps one local archive and ` + "`history`" + ` is the only command that
fills it: the calendar walk and its per-series filled-range state both live
there, along with the per-activity detail, splits and heart-rate-zone fetches
this verb used to make. Running both stored the same data twice under
different names, so this verb now prints where to go and exits 2.

Generated messages elsewhere that say "run ` + "`garmin-pp-cli sync`" + ` first"
still lead to the right place: they lead here, and here says ` + "`history`" + `.`,
		Example: `  # What to run instead
  garmin-pp-cli history`,
		// Cobra prints its own "Error: <err>" line for a RunE failure
		// unless the command silences it (newRootCmd sets SilenceUsage
		// but not SilenceErrors), and prints the usage block unless
		// SilenceUsage is set somewhere in the chain. This command's
		// entire output is one line, so it writes that line itself and
		// silences both copies here rather than relying on the root's
		// setting — the output is then the same whoever executes it.
		SilenceErrors: true,
		SilenceUsage:  true,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if flags != nil && flags.asJSON {
				// One line on stdout and nothing else, so a machine
				// caller parses a single object rather than an object
				// plus a prose line it has to ignore.
				enc := json.NewEncoder(cmd.OutOrStdout())
				if err := enc.Encode(map[string]string{
					"event":   garminSyncSupersededEvent,
					"message": garminSyncSupersededMessage,
					"hint":    "garmin-pp-cli history",
				}); err != nil {
					return err
				}
				return garminSyncSupersededErr()
			}
			fmt.Fprintln(cmd.ErrOrStderr(), garminSyncSupersededMessage)
			return garminSyncSupersededErr()
		},
	}
	return cmd
}

// garminSyncSupersededErr exits 2. It builds the cliError directly rather than
// calling usageErr so the invocation is not classified as a Cobra usage
// failure it was not: the code is the same 2 — a command that cannot do what
// was asked, told correctly — but the journal records it as a runtime outcome,
// which is what it is.
func garminSyncSupersededErr() error {
	return &cliError{code: 2, err: errors.New(garminSyncSupersededMessage)}
}
